---
import type { HTMLAttributes } from "astro/types"

import { cn } from "@/lib/utils"

type Props = HTMLAttributes<"div"> & {
  label?: string
  defaultValue?: string
  defaultSearch?: string
  shouldFilter?: boolean
  loop?: boolean
  disablePointerSelection?: boolean
  vimBindings?: boolean
}

const {
  class: className,
  label,
  defaultValue,
  defaultSearch,
  shouldFilter,
  loop,
  disablePointerSelection,
  vimBindings,
  ...props
} = Astro.props
---

<div
  data-slot="command"
  data-label={label}
  data-default-value={defaultValue}
  data-default-search={defaultSearch}
  data-should-filter={shouldFilter}
  data-loop={loop}
  data-disable-pointer-selection={disablePointerSelection}
  data-vim-bindings={vimBindings}
  class={cn(
    "bg-popover text-popover-foreground flex size-full flex-col overflow-hidden rounded-xl! p-1",
    className
  )}
  {...props}
>
  <slot />
</div>

<script>
  import { createCommand } from "@data-slot/command"
  import { getPart, getParts } from "@data-slot/core"

  import { initializeDataSlot } from "@/lib/data-slot"

  initializeDataSlot("command", (root) => {
    const controller = createCommand(root)
    // 1.x dialog autofocus includes the command's tabindex=-1 container.
    // Keep opening a command palette ready for typing, as in 0.2.x.
    const focusInput = () =>
      getPart<HTMLInputElement>(root, "command-input")?.focus({
        preventScroll: true,
      })
    root.addEventListener("focus", focusInput)
    const navigate = (event: Event) => {
      if (event.target !== root) return
      const { value } = (event as CustomEvent<{ value?: unknown }>).detail
      if (typeof value !== "string") return
      const item = getParts<HTMLAnchorElement>(root, "command-item").find(
        (item) =>
          item.getAttribute("data-value") === value && item.hasAttribute("href")
      )
      const href = item?.getAttribute("href")
      if (href) window.location.href = href
    }
    root.addEventListener("command:select", navigate)
    return {
      destroy() {
        root.removeEventListener("focus", focusInput)
        root.removeEventListener("command:select", navigate)
        controller.destroy()
      },
    }
  })
</script>

---
import type { HTMLAttributes } from "astro/types"

import { cn } from "@/lib/utils"

type Props = HTMLAttributes<"div"> & {
  heading?: string
  value?: string
  forceMount?: boolean
}

const { class: className, heading, value, forceMount, ...props } = Astro.props
---

<div
  data-slot="command-group"
  data-value={value}
  data-force-mount={forceMount ? "true" : undefined}
  class={cn(
    "text-foreground [&_[data-slot=command-group-heading]]:text-muted-foreground overflow-hidden p-1 [&_[data-slot=command-group-heading]]:px-2 [&_[data-slot=command-group-heading]]:py-1.5 [&_[data-slot=command-group-heading]]:text-xs [&_[data-slot=command-group-heading]]:font-medium",
    className
  )}
  {...props}
>
  {heading && <div data-slot="command-group-heading">{heading}</div>}
  <slot />
</div>

---
import type { HTMLAttributes } from "astro/types"
import CheckIcon from "@lucide/astro/icons/check"

import { cn } from "@/lib/utils"

type Props = HTMLAttributes<"a"> & {
  disabled?: boolean
  href?: string
  value?: string
  label?: string
  keywords?: string | string[]
  forceMount?: boolean
}

const {
  class: className,
  disabled,
  href,
  value,
  label,
  keywords,
  forceMount,
  ...props
} = Astro.props

const Tag = href ? "a" : "div"
const keywordsValue = Array.isArray(keywords) ? keywords.join(", ") : keywords
---

<Tag
  data-slot="command-item"
  data-disabled={disabled ? "true" : undefined}
  data-value={value}
  data-label={label}
  data-keywords={keywordsValue}
  data-force-mount={forceMount ? "true" : undefined}
  href={href}
  class={cn(
    "group/command-item data-selected:bg-muted data-selected:text-foreground data-selected:**:[svg]:text-foreground href:cursor-pointer href:no-underline relative flex cursor-default items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-hidden select-none in-data-[slot=dialog-content]:rounded-lg! data-[disabled=true]:pointer-events-none data-[disabled=true]:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
    className
  )}
  {...props}
>
  <slot />
  <CheckIcon
    class="ml-auto opacity-0 group-has-data-[slot=command-shortcut]/command-item:hidden group-data-selected/command-item:opacity-100"
  />
</Tag>
